import booksData from "@/assets/json/hadithBooks.json";

export type HadithBookGroup = "sahihain" | "sunan" | "other";

export interface HadithSection {
  number: number;
  title: string;
  first: number;
  last: number;
  count: number;
}

export interface HadithBook {
  key: string;
  edition: string;
  title: string;
  author: string;
  group: HadithBookGroup;
  hadithCount: number;
  hasGrades: boolean;
  sections: HadithSection[];
}

// Generated by scripts/generate-hadith-books.js from fawazahmed0/hadith-api
// (numbers, sections) and AhmedBaset/hadith-json v1.2.0 (Arabic titles).
export const HADITH_BOOKS = booksData as HadithBook[];

export const HADITH_BOOK_GROUPS: { key: HadithBookGroup; title: string }[] = [
  { key: "sahihain", title: "الصحيحان" },
  { key: "sunan", title: "السنن الأربعة" },
  { key: "other", title: "كتب أخرى" },
];

export const getHadithBook = (key: string): HadithBook | undefined =>
  HADITH_BOOKS.find((book) => book.key === key);
